import styled from 'styled-components';
import React from 'react'

const BurgerBlock = styled.div`
width:100px;
padding:30px;
background-color:black;
color:white;
margin:auto;`

const Line = styled.div`
height:4px;
width:100%;
background-color:white;
border-radius:2px;`



export const Burger = () => {
    return(
       <BurgerBlock>
        <Line></Line>
        <Line></Line>
        <Line></Line>
       </BurgerBlock>
    );
};
